assert hashlib.sha256(Path('input_review.json').read_bytes()).hexdigest()==s['input_review_sha256']
claims={x['item_id']:{u['unit_id']:[] for u in x['candidate_sentence_units']} for x in o}
def A(n,u,claim,j,role,quote,support,counter,reason,ambiguity=None):
 key=f'Q{n:03d}'; unit=f'U{u:02d}'; original=next(x for x in o[n-1]['candidate_sentence_units'] if x['unit_id']==unit)
 start=original['start']+original['quote'].index(quote)
 def cites(selections):
  result=[]
  for selection in selections:
   di=selection if isinstance(selection,int) else selection[0]
   doc=p[n-1]['documents'][di-1]
   q=doc if isinstance(selection,int) else selection[1]
   st=doc.index(q); result.append(dict(document_index=di,start=st,end=st+len(q),quote=q))
  return result
 atom=dict(claim_id=f'{key}-A{sum(len(v) for v in claims[key].values())+1:02d}',claim=claim,judgment=j,role=role,
  output_citation=dict(start=start,end=start+len(quote),quote=quote),document_support=cites(support),counterevidence=cites(counter),
  missing_link=reason,ambiguity=ambiguity or 'No material scope ambiguity is identified for this proposition: '+claim)
 claims[key][unit].append(atom)
